export interface OdsPfEnv {
  /** the placeholder of the search box of a select without a filter (label.ods.search) */
  search: string;
}

// the patches go on the prototypes of the widgets once for the page's life (odsPatchPF guards itself with this)
let pfPatched = false;

export function startOdsPf(env: OdsPfEnv): () => void {
  var disposers: (() => void)[] = [];
  var odsAutoId = 0;
  function odsText(key) { return key === 'search' ? env.search : ''; }
  function injectPfCss() {
    if (document.getElementById('odsPfCss')) { return; }
    var st = document.createElement('style');
    st.id = 'odsPfCss';
    st.textContent = PF_CSS;
    document.head.appendChild(st);
  }
  function closeAll() {
    Array.prototype.forEach.call(document.querySelectorAll('.ods-list.open'), function (l) { l.classList.remove('open'); });
    Array.prototype.forEach.call(document.querySelectorAll('.ods-btn.open'), function (b) { b.classList.remove('open'); });
  }
  var pfOpen = [];

  function pfTrack(w) { if (pfOpen.indexOf(w) === -1) { pfOpen.push(w); } }

  function pfUntrack(w) { var i = pfOpen.indexOf(w); if (i !== -1) { pfOpen.splice(i, 1); } }

  function odsPfHideOpen() {
      if (!pfOpen.length) { return; }
      var list = pfOpen.slice();
      pfOpen.length = 0;
      for (var i = 0; i < list.length; i++) {
          try { list[i].hide(); } catch (e) { /* widget ถูกทำลายไปแล้ว (ajax update) */ }
      }
  }

  function pfWrapShowHide(proto) {
      if (!proto || proto.__odsTracked) { return; }
      proto.__odsTracked = true;
      var origShow = proto.show, origHide = proto.hide;
      if (typeof origShow === "function") {
          proto.show = function () { var r = origShow.apply(this, arguments); pfTrack(this); return r; };
      }
      if (typeof origHide === "function") {
          proto.hide = function () { pfUntrack(this); return origHide.apply(this, arguments); };
      }
  }

  function odsPatchPF() {
      if (pfPatched || !window.PrimeFaces || !PrimeFaces.widget) { return; }
      var W = PrimeFaces.widget;
      if (W.SelectOneMenu && W.SelectOneMenu.prototype) {
          pfPatched = true;
          W.SelectOneMenu.prototype.alignPanel = function () {
              if (!this.panel || !this.panel.length) { return; }
              var trigger = this.jq && this.jq[0];
              var panel = this.panel[0];
              if (!trigger || !panel) { return; }
              // กางลงใต้ trigger เสมอด้วย position:fixed + getBoundingClientRect
              // (jQuery UI .position() เพี้ยนเมื่อมี ancestor ที่มี transform เช่น .layout-main
              //  → panel เปิดมาทับ trigger; ใช้วิธีเดียวกับ dropdown native ODS ที่ชนะ transform เสมอ)
              var r = trigger.getBoundingClientRect();
              panel.style.position = "fixed";
              panel.style.left = Math.round(r.left) + "px";
              panel.style.top = Math.round(r.bottom + 4) + "px";
              panel.style.minWidth = Math.round(r.width) + "px";
              // พื้นที่ล่างไม่พอ → หดความสูงลิสต์ให้พอดีจอ (เลื่อนดูในลิสต์แทนการ flip)
              var w = (this.itemsWrapper && this.itemsWrapper.length) ? this.itemsWrapper : this.panel.find(".ui-selectonemenu-items-wrapper");
            if (w && w.length) {
                w.css("max-height", "none");
                var chrome = Math.max(0, panel.offsetHeight - w[0].offsetHeight);
                var below = window.innerHeight - r.bottom - 12, above = r.top - 12;
                var want = Math.min(w[0].scrollHeight, 320);
                var up = (below - chrome < Math.min(want, 200)) && above > below;
                var room = Math.max(96, (up ? above : below) - chrome - 4);
                w.css("max-height", Math.min(320, room) + "px");
                if (up) { panel.style.top = Math.max(8, Math.round(r.top - 4 - panel.offsetHeight)) + "px"; }
            }
              // ล้นขอบขวาจอ → ขยับเข้ามา
              var pw = panel.offsetWidth;
              if (r.left + pw > window.innerWidth - 8) {
                  panel.style.left = Math.max(8, window.innerWidth - 8 - pw) + "px";
              }
          };
          var origShow = W.SelectOneMenu.prototype.show;
          W.SelectOneMenu.prototype.show = function () {
              odsPfSearch(this);
              origShow.call(this);
              pfTrack(this);   // ★ จดว่าแผงนี้เปิดอยู่ — ใช้ปิดตอนเลื่อนจอ (ดู odsPfHideOpen)
              var self = this;
              setTimeout(function () {
                  var s = self.panel && self.panel[0] && self.panel[0].querySelector(".ods-search");
                  if (s) { s.focus(); }
              }, 60);
          };
          var origHide = W.SelectOneMenu.prototype.hide;
          if (typeof origHide === "function") {
              W.SelectOneMenu.prototype.hide = function () {
                  pfUntrack(this);
                  return origHide.apply(this, arguments);
              };
          }
          W.SelectOneMenu.prototype.__odsTracked = true;   // กัน pfWrapShowHide ครอบซ้ำ
      }
      if (W.SelectCheckboxMenu && W.SelectCheckboxMenu.prototype && W.SelectCheckboxMenu.prototype.alignPanel) {
          pfWrapShowHide(W.SelectCheckboxMenu.prototype);   // ★ จดสถานะเปิด/ปิด — ปิดตอนเลื่อนจอ
          W.SelectCheckboxMenu.prototype.alignPanel = function () {
              if (!this.panel || !this.panel.length) { return; }
              var trigger = this.jq && this.jq[0];
              var panel = this.panel[0];
              if (!trigger || !panel) { return; }
              // กางลงใต้ trigger เสมอด้วย position:fixed + getBoundingClientRect (ชนะ ancestor transform)
              var r = trigger.getBoundingClientRect();
              panel.style.position = "fixed";
              panel.style.left = Math.round(r.left) + "px";
              panel.style.top = Math.round(r.bottom + 4) + "px";
              panel.style.minWidth = Math.round(r.width) + "px";
              var pw = panel.offsetWidth;
              if (r.left + pw > window.innerWidth - 8) {
                  panel.style.left = Math.max(8, window.innerWidth - 8 - pw) + "px";
              }
          };
      }
  }

  function odsPfSearch(widget) {
      var panel = widget.panel && widget.panel[0];
      if (!panel) { return; }
      if (panel.querySelector(".ui-selectonemenu-filter-container")) { return; }   // มี filter ของ PF อยู่แล้ว
      var box = panel.querySelector(".ods-pf-filter");
      if (!box) {
          injectPfCss();
          box = document.createElement("div");
          box.className = "ods-pf-filter";
          var inp = document.createElement("input");
          inp.type = "text";
          inp.className = "ods-search";
          inp.placeholder = odsText("search");
          inp.setAttribute("autocomplete", "off");
          box.appendChild(inp);
          panel.insertBefore(box, panel.firstChild);
          inp.addEventListener("click", function (e) { e.stopPropagation(); });
          inp.addEventListener("keydown", function (e) {
              if (e.key === "Escape") { widget.hide(); return; }
              if (e.key === "Enter") {
                  e.preventDefault();
                  e.stopPropagation();
                  var vis = null, all = panel.querySelectorAll(".ui-selectonemenu-item");
                  for (var i = 0; i < all.length; i++) {
                      if (all[i].style.display !== "none") { vis = all[i]; break; }
                  }
                  if (vis) { vis.click(); }
                  return;
              }
              e.stopPropagation();   // กัน keyboard-nav ของ PF แย่งคีย์ระหว่างพิมพ์
          });
          inp.addEventListener("input", function () {
              var q = inp.value.toLowerCase();
              Array.prototype.forEach.call(panel.querySelectorAll(".ui-selectonemenu-item"), function (n) {
                  n.style.display = (!q || n.textContent.toLowerCase().indexOf(q) !== -1) ? "" : "none";
              });
              // กลุ่ม (optgroup) ที่ลูกโดนซ่อนหมด → ซ่อนหัวกลุ่มด้วย
              Array.prototype.forEach.call(panel.querySelectorAll(".ui-selectonemenu-item-group"), function (gk) {
                  var sib = gk.nextElementSibling, any = false;
                  while (sib && !sib.classList.contains("ui-selectonemenu-item-group")) {
                      if (sib.style.display !== "none") { any = true; break; }
                      sib = sib.nextElementSibling;
                  }
                  gk.style.display = (!q || any) ? "" : "none";
              });
          });
      }
      // reset ทุกครั้งที่เปิด
      var inp2 = box.querySelector("input");
      if (inp2) { inp2.value = ""; }
      Array.prototype.forEach.call(panel.querySelectorAll(".ui-selectonemenu-item,.ui-selectonemenu-item-group"), function (n) { n.style.display = ""; });
  }

  function odsEnhancePfYear(inp) {
      if (!inp || inp.getAttribute("data-ods") === "1") { return; }
      injectPfCss();
      inp.setAttribute("data-ods", "1");
      inp.style.display = "none";

      var btn = document.createElement("div");
      btn.className = "ods-btn";
      btn.innerHTML = '<span class="ods-txt"></span><i class="pi pi-chevron-down ods-ic"></i>';
      inp.parentNode.insertBefore(btn, inp.nextSibling);
      btn._odsSel = inp;

      var list = document.createElement("div");
      list.className = "ods-list ods-nocheck";
      var items = document.createElement("div");
      items.className = "ods-items";
      list.appendChild(items);
      document.body.appendChild(list);
      btn._odsList = list;

      function sync() { btn.querySelector(".ods-txt").textContent = inp.value || ""; }
      function render() {
          var cur = parseInt(inp.value, 10) || new Date().getFullYear();
          var from = cur - 100, to = cur + 10, html = "", y;   // ช่วงเดียวกับ .ods-cal-dlist ของ odsDate เอง
          for (y = from; y <= to; y++) {
              html += '<div class="ods-item' + (y === cur ? " sel" : "") + '" data-v="' + y + '">' + y + "</div>";
          }
          items.innerHTML = html;
      }
      function openList() {
          render();
          var r = btn.getBoundingClientRect();
          list.style.left = Math.round(r.left) + "px";
          list.style.top = Math.round(r.bottom + 4) + "px";
          list.style.minWidth = Math.round(r.width) + "px";
          list.style.width = "auto";
          var room = window.innerHeight - r.bottom - 16;
          items.style.maxHeight = Math.max(120, Math.min(216, room - 12)) + "px";
          list.classList.add("open");
          btn.classList.add("open");
          var lw = list.offsetWidth;
          if (r.left + lw > window.innerWidth - 8) {
              list.style.left = Math.max(8, window.innerWidth - 8 - lw) + "px";
          }
          var sel = items.querySelector(".ods-item.sel");
          if (sel) { sel.scrollIntoView({block: "center"}); }
      }
      btn.addEventListener("click", function (e) {
          e.stopPropagation();
          var isOpen = list.classList.contains("open");
          closeAll();
          if (!isOpen) { openList(); }
      });
      list.addEventListener("click", function (e) { e.stopPropagation(); });
      items.addEventListener("click", function (e) {
          var it = e.target.closest ? e.target.closest(".ods-item") : null;
          if (!it) { return; }
          inp.value = it.getAttribute("data-v");
          list.classList.remove("open");
          btn.classList.remove("open");
          sync();
          inp.dispatchEvent(new Event("change", { bubbles: true }));
      });
      inp.addEventListener("change", sync);
      sync();
  }

  var odsEnhancePfNav = function (root) {
      root = (root && root.querySelectorAll) ? root : document;
      var sels = root.querySelectorAll("select.ui-datepicker-month");
      Array.prototype.forEach.call(sels, function (sel) {
          if (sel.getAttribute("data-ods") === "1") { return; }
          sel.setAttribute("data-ods-nosearch", "1");   // แค่ 12 เดือน ไม่ต้องมีช่องค้นหา
          if (!sel.id) { sel.id = "odsAuto_" + (++odsAutoId); }
          window.odsEnhance(sel.id);
      });
      // ★ 27/08: "ปี" ของ p:calendar/p:datePicker เป็น <input type="number"> ไม่ใช่ select — window.odsEnhance
      //   ใช้กับมันไม่ได้ (อ่าน sel.options) ทำ list ปีเองเลียนแบบ .ods-cal-dlist ของ odsDate (ช่วง -100/+10 ปี
      //   จากปีปัจจุบันในช่อง เหมือนกัน) ให้เป็น dropdown กดได้แทนลูกศร spinner เฉย ๆ ตามรูปตัวอย่างที่ user ส่งมา
      var yearInputs = root.querySelectorAll("input.ui-datepicker-year");
      Array.prototype.forEach.call(yearInputs, function (inp) {
          odsEnhancePfYear(inp);
      });
  }

  function closeAllViewportAnchored() { closeAll(); odsPfHideOpen(); }
  var SCROLL_KEEP_SEL = '.ods-list,.ui-selectonemenu-panel,.ui-selectcheckboxmenu-panel,.ui-autocomplete-panel,.ld2-prod-dd';
  function onScroll(e) {
    if (e.target && e.target.closest && e.target.closest(SCROLL_KEEP_SEL)) { return; }
    closeAllViewportAnchored();
  }
  window.addEventListener('resize', closeAllViewportAnchored);
  window.addEventListener('scroll', onScroll, true);
  disposers.push(function () { window.removeEventListener('resize', closeAllViewportAnchored); window.removeEventListener('scroll', onScroll, true); });

  // boot(): the style, the patches, the calendars that are there; and the ones drawn later (the datepicker header is built by PrimeFaces when it opens)
  injectPfCss();
  odsPatchPF();
  odsEnhancePfNav(document);
  var pend = null;
  var observer = new MutationObserver(function (muts) {
    for (var i = 0; i < muts.length; i++) {
      var add = muts[i].addedNodes;
      for (var j = 0; j < add.length; j++) {
        var n = add[j];
        if (n.nodeType === 1 && (n.tagName === 'SELECT' || n.tagName === 'INPUT' || (n.querySelector && n.querySelector('select,input')))) {
          if (!pend) { pend = setTimeout(function () { pend = null; odsEnhancePfNav(document); }, 80); }
          return;
        }
      }
    }
  });
  observer.observe(document.body, { childList: true, subtree: true });
  disposers.push(function () { observer.disconnect(); if (pend) { clearTimeout(pend); } });

  return function destroy() {
    disposers.splice(0).forEach(function (d) { d(); });
    var st = document.getElementById('odsPfCss');
    if (st) { st.remove(); }
  };
}
